import glob
import pandas as pd


def load(d):
    f = glob.glob(f'data/{d}/API_*.csv')[0]
    return pd.read_csv(f, skiprows=4, encoding='utf-8-sig').dropna(axis=1, how='all')


for d in ['life_expectancy', 'health_expenditure_per_capita', 'gdp_per_capita_ppp']:
    df = load(d)
    yrs = [c for c in df.columns if c.isdigit()]
    print(d, df.shape, {y: int(df[y].notna().sum()) for y in yrs[-8:]})
    print(df[df['Country Code'] == 'VNM'][yrs[-8:]].to_string())

